WITH cleaned AS (SELECT id, store_name, region, opened_date, UPPER(TRIM(store_name)) AS store_name_normalized FROM stores WHERE opened_date BETWEEN '2025-03-01' AND '2025-10-01') SELECT s.*, x.units, x.store_sale_revenue FROM cleaned s JOIN LATERAL (SELECT c.units, c.revenue AS store_sale_revenue FROM store_sales c WHERE c.store_id = s.id ORDER BY c.sale_date DESC, c.id DESC LIMIT 1) x ON TRUE;
